export interface MerkleSnapshot {
  readonly path: string;
  readonly sha256: string;
}

export function detectChangedSubtrees(
  previousIndex: ReadonlyMap<string, string>,
  currentWorkspace: readonly MerkleSnapshot[]
): readonly string[] {
  const dirtyPaths: string[] = [];
  for (const node of currentWorkspace) {
    if (previousIndex.get(node.path) !== node.sha256) {
      dirtyPaths.push(node.path);
    }
  }
  return dirtyPaths;
}

export async function retrieveCorpDocs(
  vectorDb: VectorStore,
  userRoles: readonly string[],
  queryVector: readonly number[],
  topK: number
): Promise<readonly DocChunk[]> {
  const candidates = await vectorDb.similaritySearch(queryVector, { limit: topK });
  return candidates.filter((doc) =>
    doc.allowedRoleIds.some((role) => userRoles.includes(role))
  );
}

export function evaluateMoatSample(arch: AiProductArchitecture) {
  const warnings: string[] = [];
  const contextAndDataGravity =
    (arch.hasProprietaryConnectors ? 12 : 0) +
    (arch.enforcesAclPreFiltering ? 10 : 0) +
    (arch.hasFeedbackEvalFlywheel ? 8 : 0);
  let domainUxAndWorkflow = 0;
  if (!arch.usesBlankChatAsPrimaryUi) domainUxAndWorkflow += 12;
  if (arch.usesStructuredOutputsAndStateMachine) domainUxAndWorkflow += 13;
  const multiModelAndInference =
    (arch.hasMultiModelRoutingAndFallback ? 15 : 0) +
    (arch.implementsPromptCaching ? 10 : 0);
  const enterpriseCompliance = arch.hasPiiRedactionAndAuditLog ? 20 : 0;
  let penalty = 0;
  if (arch.reliesOnSingleSystemPrompt) penalty += 15;
  if (!arch.enforcesAclPreFiltering && arch.hasProprietaryConnectors) {
    penalty += 10;
    warnings.push('Vulnerabilidade crítica: conectores sem filtragem prévia de ACL/RBAC.');
  }
  const raw = contextAndDataGravity + domainUxAndWorkflow + multiModelAndInference + enterpriseCompliance;
  const totalScore = Math.max(0, Math.min(100, raw - penalty));
  const classification = totalScore >= 75 ? 'AI_NATIVE_DEFENSIBLE' : totalScore >= 45 ? 'FEATURE_ADDON' : 'SHALLOW_WRAPPER';
  const sherlockingRisk = totalScore >= 75 ? 'LOW' : totalScore >= 45 ? 'MEDIUM' : 'HIGH';
  return { totalScore, classification, sherlockingRisk, warnings };
}

