export function extractInvoiceRisk(markdownOutput: string): { totalUsd: number; risky: boolean } {
  const totalMatch = markdownOutput.match(/## Total:\s*USD\s*([0-9.]+)/);
  const riskMatch = markdownOutput.match(/Risco:\s*(ALTO|BAIXO)/);
  return {
    totalUsd: totalMatch ? Number(totalMatch[1]) : 0,
    risky: riskMatch ? riskMatch[1] === 'ALTO' : false,
  };
}

export async function dispatchWithGovernance(
  rawPayload: string,
  complexity: 'simple' | 'deep',
  primary: LlmAdapter,
  fallback: LlmAdapter,
  traceLog: (meta: { model: string; usedFallback: boolean }) => void
): Promise<string> {
  const sanitizedPayload = redactPiiAndSecrets(rawPayload);
  const selectedTier = complexity === 'simple' ? 'fast-economic' : 'frontier-reasoning';
  try {
    const res = await primary.invoke(sanitizedPayload, { tier: selectedTier, zdr: true, timeoutMs: 8000 });
    traceLog({ model: res.modelId, usedFallback: false });
    return res.outputJson;
  } catch (err) {
    if (!isTransientCapacityError(err)) throw err;
    const res = await fallback.invoke(sanitizedPayload, { tier: selectedTier, zdr: true, timeoutMs: 8000 });
    traceLog({ model: res.modelId, usedFallback: true });
    return res.outputJson;
  }
}

export function computeSingleRequestCostUsd(): number {
  const avgInputTokens = 20_000;
  const cacheHitRatio = 0.8;
  const avgOutputTokens = 500;
  const inputUsdPerMillion = 3.0;
  const cachedInputUsdPerMillion = 0.3;
  const outputUsdPerMillion = 15.0;

  const uncachedTokens = avgInputTokens * (1 - cacheHitRatio);
  const cachedTokens = avgInputTokens * cacheHitRatio;

  return (
    (uncachedTokens * inputUsdPerMillion +
      cachedTokens * cachedInputUsdPerMillion +
      avgOutputTokens * outputUsdPerMillion) /
    1_000_000
  );
}

export function computeRequestCeiling() {
  const monthlyArpuUsd = 25.0;
  const fixedInfraPerUserUsd = 2.5;
  const targetGrossMarginPct = 70;
  const weightedAvgReqCostUsd = 0.05;

  const allowedTokenBudgetUsd =
    monthlyArpuUsd * (1 - targetGrossMarginPct / 100) - fixedInfraPerUserUsd;
  const maxAvgRequestsForTargetMargin = Math.max(
    0,
    Math.floor(allowedTokenBudgetUsd / weightedAvgReqCostUsd)
  );

  return { allowedTokenBudgetUsd, maxAvgRequestsForTargetMargin };
}

